    @Test void realCommittedCustomAndExpertSourcesExportAllFourFormatsWithoutChangingFrozenFacts()throws Exception{
        String sid=newRelationSession(true).path("id").asText(),id=finishRealRelations(sid,true,"S");var arb=identity.authenticate("Bearer "+arbiter);transition(id,"FV03");transition(id,"TRIAL_FV05");commits.commitTrial(arb,id,VersionJson.uuid(),finals.read(arb,id).path("version").path("recordVersion").asInt(),mapper.createObjectNode().put("confirmed",true),VersionJson.uuid());var before=finals.read(arb,id);var owner=identity.authenticate("Bearer "+creator);
        for(String format:List.of("JSON","XLSX","PNG","SVG")){
            var body=mapper.createObjectNode().put("format",format);body.putArray("finalVersionIds").add(id);body.putArray("include");boolean graph=List.of("PNG","SVG").contains(format);String key=VersionJson.uuid();var record=graph?exports.createGraph(owner,key,body):exports.create(owner,key,body);assertThat(graph?exports.createGraph(owner,key,body):exports.create(owner,key,body)).isEqualTo(record);
            assertThat(exportWorker.processOne()).isTrue();var ready=exports.read(owner,record.path("id").asText());assertThat(ready.path("status").asText()).as(ready.toString()).isEqualTo("COMPLETED");var tk=exports.ticket(owner,record.path("id").asText(),false,VersionJson.uuid(),mapper.createObjectNode().put("purpose","第六批真实来源回验"),VersionJson.uuid());int count=exportStore.events().size();byte[] bytes=exports.content(owner,tk.path("fileId").asText(),tk.path("downloadToken").asText()).bytes();assertThat(exports.content(owner,tk.path("fileId").asText(),tk.path("downloadToken").asText()).bytes()).isEqualTo(bytes);assertThat(exportStore.events()).hasSize(count);
            var input=exportStore.input(record.path("id").asText());assertThat(input.path("segmentationSubmissions")).hasSize(2);assertThat(input.path("customReferences")).hasSize(2);assertThat(input.path("expertReferences")).hasSize(1);assertThat(input.path("sourceVersions")).hasSize(2);
            if(format.equals("JSON")){assertThat(mapper.readTree(bytes).path("participants")).hasSize(2);assertThat(mapper.readTree(bytes).path("customReferences")).isEqualTo(input.path("customReferences"));}
            if(format.equals("XLSX")){try(var zip=new java.util.zip.ZipInputStream(new java.io.ByteArrayInputStream(bytes))){boolean found=false;for(java.util.zip.ZipEntry e;(e=zip.getNextEntry())!=null;)if(e.getName().equals("xl/workbook.xml")){String xml=new String(zip.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);assertThat(xml).contains("CustomReferences","ExpertReferences","SegmentationSubmissions");found=true;}assertThat(found).isTrue();}}
            if(graph){var manifest=ready.path("generatedMetadata").path("componentManifest");assertThat(manifest).hasSize(1);assertThat(manifest.get(0).path("nodeIds")).hasSize(3);assertThat(manifest.get(0).path("edgeIds")).hasSize(2);assertThat(manifest.get(0).path("contentDigest").asText()).isEqualTo(com.argument.finalreview.FinalReviewService.contentDigest(before));}
            if(format.equals("PNG"))assertThat(javax.imageio.ImageIO.read(new java.io.ByteArrayInputStream(bytes))).isNotNull();if(format.equals("SVG"))assertThat(new String(bytes,java.nio.charset.StandardCharsets.UTF_8)).contains("<svg","D BRANCH TRIAL");
        }
        assertThat(finals.read(arb,id)).isEqualTo(before);assertThat(exportStore.exports()).hasSize(4);
    }
