    ObjectNode newRelationSession()throws Exception{return newRelationSession(false);}
    ObjectNode newRelationSession(boolean propositionCustom)throws Exception{
        confirmForDraft();var ids=mapper.createArrayNode();int version=0;
        for(String[] pair:List.of(new String[]{chen,chenAssignment},new String[]{liu,liuAssignment})){
            var actor=identity.authenticate("Bearer "+pair[0]);String draft=createDraft(pair[0],pair[1]).path("id").asText();element(pair[0],draft,5,20,propositionCustom&&version==1?"GM-I":"GM-L");element(pair[0],draft,20,39,"GM-L");
            var es=data.find("element","ownerId",draft).stream().sorted(Comparator.comparingInt(e->e.path("startOffset").asInt())).toList();structures.create(actor,draft,VersionJson.uuid(),relationBody("S",es.get(version%2).path("id").asText(),es.get((version+1)%2).path("id").asText()));validateDraft(pair[0],draft);ids.add(versionService.submit(actor,draft,VersionJson.uuid(),data.read("draft",draft).path("recordVersion").asInt(),true,"").path("id").asText());version++;
        }
        var request=mapper.createObjectNode();request.set("sourceVersionIds",ids);var actor=identity.authenticate("Bearer "+arbiter);var session=adjud.create(actor,caseId,VersionJson.uuid(),request);String id=session.path("id").asText();
        decideAllPropositions(id);

        return adjud.complete(actor,id,VersionJson.uuid(),sessions.session(id,false).path("recordVersion").asInt(),mapper.createObjectNode().put("confirmed",true),"PROPOSITION");
    }

