    void realExpert(String id,String itemId,String kind)throws Exception{var actor=identity.authenticate("Bearer "+arbiter);var expert=identity.authenticate("Bearer "+login("expert.qian"));if(data.find("member","taskId",taskId).stream().noneMatch(m->expert.id().equals(m.path("userId").asText())))send("/api/v1/tasks/"+taskId+"/members",creator,VersionJson.uuid(),mapper.createObjectNode().put("userId",expert.id()).put("memberRole","EXPERT"),null,200);var requested=reviews.escalate(actor,id,VersionJson.uuid(),sessions.session(id,false).path("recordVersion").asInt(),mapper.createObjectNode().put("expertUserId",expert.id()).put("itemKind",kind).put("itemId",itemId).put("question","核查本轮关系方向及指南依据"));String review=requested.path("review").path("id").asText(),issue=requested.path("issues").get(0).path("id").asText();reviews.start(expert,review,VersionJson.uuid(),1,mapper.createObjectNode().put("action","START"));reviews.resolve(expert,issue,VersionJson.uuid(),1,mapper.createObjectNode().put("resolution","本轮应按命题含义重新确认关系").put("guideBasis","指南 S/A 关系类型及方向规则"));reviews.confirm(expert,review,VersionJson.uuid(),2,mapper.createObjectNode().put("confirmed",true));}
    ObjectNode customRelationBody(String id,ObjectNode item,String code){var unified=data.read("unifiedSnapshot",data.read("adjudicationMapping",id).path("unifiedSnapshotId").asText());var body=mapper.createObjectNode().put("itemKind","RELATION").put("itemId",item.path("id").asText()).put("reason","依据本轮指南与专家结论补正");var inputs=body.putArray("customElements");int index=0;for(var element:unified.path("elements")){var input=inputs.addObject().put("clientKey","p"+(++index));for(String field:List.of("startOffset","endOffset","labelCode","sourceElementIds"))input.set(field,element.get(field));}var relation=body.putArray("customRelations").addObject().put("clientKey","r").put("relationCode",code);relation.set("sourceRelationIds",item.get("candidateRelationIds"));var parts=relation.putArray("participants");parts.addObject().put("ordinal",1).put("role","SOURCE").put("targetKind","ELEMENT").put("targetClientKey","p1");parts.addObject().put("ordinal",2).put("role","TARGET").put("targetKind","ELEMENT").put("targetClientKey","p2");return body;}
    String finishRealRelations(String id,boolean expert,String code)throws Exception{var actor=identity.authenticate("Bearer "+arbiter);var item=sessions.items(id,"RELATION").get(0);if(expert)realExpert(id,item.path("id").asText(),"RELATION");item=sessions.item(item.path("id").asText(),"RELATION");var custom=reviews.saveCustom(actor,id,VersionJson.uuid(),customRelationBody(id,item,code));adjud.decideRelation(actor,item.path("id").asText(),VersionJson.uuid(),item.path("recordVersion").asInt(),mapper.createObjectNode().put("action","CUSTOM").put("customAnnotationId",custom.path("annotation").path("id").asText()).put("reason","确认采用本轮独立关系快照"));adjud.complete(actor,id,VersionJson.uuid(),sessions.session(id,false).path("recordVersion").asInt(),mapper.createObjectNode().put("confirmed",true),"RELATION");return finals.create(actor,id,VersionJson.uuid(),finals.listLocal(actor,id).path("nextVersionNumber").asInt()).path("id").asText();}
